theorem prawitz_budget_cutoffs
    (ρ : ℝ) (hρ : 0 < ρ) (hρ1 : ρ < 1) :
    let U0 := max (3 / 2 : ℝ) (Real.sqrt (4 * Real.log (1 / ρ)))
    let U := 12 / (5 * ρ)
    0 < U0 ∧ U0 ≤ U

theorem prawitz_budget_high_compact
    (ρ : ℝ) (hlarge : 1 / 100 < ρ) (hρ1 : ρ < 1) :
    let U0 := max (3 / 2 : ℝ) (Real.sqrt (4 * Real.log (1 / ρ)))
    let U := 12 / (5 * ρ)
    (2 / U) * (∫ t in U0..U,
      ‖prawitzKernel (t / U)‖ * prawitzMomentEnvelope ρ t) ≤ 3 * ρ / 20

theorem prawitz_budget_high_small
    (ρ : ℝ) (hρ : 0 < ρ) (hsmall : ρ ≤ 1 / 100) :
    let U0 := max (3 / 2 : ℝ) (Real.sqrt (4 * Real.log (1 / ρ)))
    let U := 12 / (5 * ρ)
    (2 / U) * (∫ t in U0..U,
