theorem prawitz_low_real_initial_enclosure (j : Fin 270) :
    let s := (prawitzCompactRight j.val : ℝ)
    let a := (1 / 200 : ℝ)
    (1 / Real.pi + 5 * s * a / 12) *
      (1 / 6 + s * a / 8) * a ^ 3 / 3 ≤
        (prawitzRationalLowInitial j.val : ℝ)

theorem prawitz_budget_low_small
    (ρ : ℝ) (hρ : 0 < ρ) (hsmall : ρ ≤ 1 / 100) :
