      fderiv ℝ (fderiv ℝ (iteratedFDeriv ℝ n u)) x b a

theorem joinAt_continuous (a : ℝ) {f g : ℝ → ℝ}
    (hf : Continuous f) (hg : Continuous g) (hv : f a = g a) :
    Continuous (joinAt a f g)

theorem leftClosedExteriorCollar_inter_cube (d m : ℕ) (i : Fin d) :
    leftClosedExteriorCollar d m i ∩ cube d =
      {x ∈ cube d | x i = -1}

theorem ScaledJetBounds.first_lipschitz {β h C : ℝ} {f : E → ℝ}
    (hf : ScaledJetBounds β h f C) (x y : E) :
    ‖fderiv ℝ f x - fderiv ℝ f y‖ ≤ C * h ^ (β - 2) * ‖x - y‖

theorem ScaledJetBounds.value_lipschitz {β h C : ℝ} {f : E → ℝ}
    (hf : ScaledJetBounds β h f C) (x y : E) :
    |f x - f y| ≤ C * h ^ (β - 1) * ‖x - y‖

theorem exists_jetBounds_of_compactSupport {f : E → ℝ}
    (hf : ContDiff ℝ 2 f) (hc : HasCompactSupport f) :
    ∃ C : ℝ, 1 ≤ C ∧ JetBounds f C

theorem SupportSeparation.unique {K : ι → Set E} {h δ : ℝ}
    (hsep : SupportSeparation K h δ) (hh : 0 < h) (hδ : 0 < δ)
    {i j : ι} {x : E} (hi : x ∈ K i) (hj : x ∈ K j) : i = j

theorem coordJetOn_unitCube_eq_ambient {d j : ℕ}
    {u : (Fin d → ℝ) → ℝ}
    (hu : ContDiff ℝ ((⊤ : ℕ∞) : WithTop ℕ∞) u)
    (f : Fin j → Fin d) (x : Fin d → ℝ) (hx : x ∈ unitCube d) :
    coordJetOn (unitCube d) j u f x =
      iteratedFDeriv ℝ j u x (fun k => Pi.single (f k) (1 : ℝ))

lemma taylorWithinEval_eq_taylorPoly {f : ℝ → ℝ} {p n : ℕ} {x₀ x : ℝ}
    (hf : ContDiff ℝ p f) (hn : n ≤ p) (hx : x₀ < x) :
    taylorWithinEval f n (Set.Icc x₀ x) x₀ x = taylorPoly n f x₀ x

theorem normalizedLogDerivCircleIntegral_centeredMonomial {c a : ℂ} {R : ℝ} {n : ℕ}
    (hR : 0 < R) (ha : a ∈ ball c R) :
    normalizedLogDerivCircleIntegral (fun z ↦ (z - a) ^ n) c R = (n : ℂ)

theorem unitCircle_maximalSeparated_covers {sites : Finset Plane} {r : ℝ}
    (hr : 0 < r) (hmax : IsMaximalSeparated sites r) :
    CoversUnitCircle sites r

theorem annularNormalizer_finite_pos {κ δ : ℝ}
    (hκ : 2 < κ) (hδpos : 0 < δ) (hδlt : δ < 1) :
    IntegrableOn (powerWeight κ) (annularTube δ) ∧ 0 < annularNormalizer κ δ

theorem applyFunction_eq_sum_projector {n : ℕ} {A : RectMatrix n n}
    (D : RealDiagonalization A) (f : ℝ → ℝ) :
    D.applyFunction f = ∑ x ∈ D.spectralValues, f x • D.projector x

theorem applyFunction_independent {n : ℕ} {A : RectMatrix n n}
    (D D' : RealDiagonalization A) (f : ℝ → ℝ) :
    D.applyFunction f = D'.applyFunction f

theorem norm_applyFunction_sub_le {n : ℕ} {A B : RectMatrix n n}
    (DA : RealDiagonalization A) (DB : RealDiagonalization B)
    (f : ℝ → ℝ) (hf : LipschitzWith 1 f) {κA κB : ℝ}
    (hκA : DA.conditionNumber ≤ κA) (hκB : DB.conditionNumber ≤ κB) :
    ‖DA.applyFunction f - DB.applyFunction f‖ ≤
      (DA.specCount : ℝ) * (DB.specCount : ℝ) * κA * κB * ‖A - B‖

theorem norm_applyFunction_sub_le_dim_sq {n : ℕ} {A B : RectMatrix n n}
    (DA : RealDiagonalization A) (DB : RealDiagonalization B)
    (f : ℝ → ℝ) (hf : LipschitzWith 1 f) {κA κB : ℝ}
    (hκA : DA.conditionNumber ≤ κA) (hκB : DB.conditionNumber ≤ κB) :
    ‖DA.applyFunction f - DB.applyFunction f‖ ≤
      (n : ℝ) ^ 2 * κA * κB * ‖A - B‖

theorem norm_projector_le_conditionNumber {n : ℕ} {A : RectMatrix n n}
    (D : RealDiagonalization A) (x : ℝ) :
    ‖D.projector x‖ ≤ D.conditionNumber

theorem projector_independent {n : ℕ} {A : RectMatrix n n}
    (D D' : RealDiagonalization A) (x : ℝ) :
    D.projector x = D'.projector x

theorem sum_projector_eq_one {n : ℕ} {A : RectMatrix n n}
    (D : RealDiagonalization A) :
    ∑ x ∈ D.spectralValues, D.projector x = 1

theorem gram_add_lambda_posDef {X : Type*} {n : ℕ} {k : X → X → ℝ}
    (hk : IsPSDkernel k) (x : Fin n → X) {lam : ℝ} (hlam : 0 < lam) :
    (gram k x + lam • (1 : Matrix (Fin n) (Fin n) ℝ)).PosDef

theorem add_mono {I I' J J' : RatInterval}
    (hI : I.Subinterval I') (hJ : J.Subinterval J') :
    (add I J).Subinterval (add I' J')

theorem mul_mono {I I' J J' : RatInterval}
    (hI : I.Subinterval I') (hJ : J.Subinterval J') :
    (mul I J).Subinterval (mul I' J')

theorem sub_mono {I I' J J' : RatInterval}
    (hI : I.Subinterval I') (hJ : J.Subinterval J') :
    (sub I J).Subinterval (sub I' J')

theorem tighten_sound {I J : RatInterval} {x : ℝ}
    (hI : I.Contains x) (hJ : J.Contains x) :
    (tighten I J).Contains x

theorem tighten_subinterval_left {I J : RatInterval} {x : ℝ}
    (hI : I.Contains x) (hJ : J.Contains x) :
    (tighten I J).Subinterval I

theorem finiteRefine_width {n : ℕ} {candidates : Fin (n + 1) → RatInterval}
    (ε : PosRat) (h : ∃ i, (candidates i).width ≤ ε.1) :
    (finiteRefine candidates ε).width ≤ ε.1

theorem tighten_subinterval_right {I J : RatInterval} {x : ℝ}
    (hI : I.Contains x) (hJ : J.Contains x) :
    (RatInterval.tighten I J).Subinterval J

theorem rpowInterval_sound {base exponent : RatInterval} {x y : ℝ}
    (hbase : 0 < base.lo) (hx : base.Contains x) (hy : exponent.Contains y) (n : ℕ) :
    (rpowInterval base exponent hbase n).Contains (x ^ y)

theorem maxAbs_le_of_contains_width {I : RatInterval} {x : ℝ}
    {C w : ℚ} (hx : I.Contains x) (habs : |x| ≤ C) (hw : I.width ≤ w) :
    I.maxAbs ≤ C + w

theorem sqrtInterval_sound {I : RatInterval} (hI : 0 ≤ I.lo) {x : ℝ}
    (hx : I.Contains x) (fuel : ℕ) :
    (sqrtInterval I hI fuel).Contains (Real.sqrt x)

theorem div_sound {I J : ComplexRatInterval} {z w : ℂ}
    (hJ : (normSq J).AwayFromZero) (hz : I.Contains z) (hw : J.Contains w) :
    (div I J hJ).Contains (z / w)

theorem tighten_sound_left {I J : ComplexRatInterval} {z : ℂ}
    (hI : I.Contains z) (hJ : J.Contains z) :
    (tighten I J).Contains z ∧ (tighten I J).Subinterval I

theorem complexExp_sound {I : ComplexRatInterval} {z : ℂ}
    (hz : I.Contains z) (fuel : ℕ) :
    (complexExp I fuel).Contains (Complex.exp z)

theorem circleNode_sound (radius : ℚ) (schedule : Schedule) {k : ℕ}
    (hk : k ≤ schedule.mesh) :
    (circleNode radius schedule k).Contains (exactCircleNode radius schedule k)
